sp_widget.client_script:
api.controller = function () {
    var c = this;
    c.year = new Date().getFullYear();
};

sp_widget.css:
.dpp-verify-wrapper {
  display: flex;
  justify-content: center;
  padding: 40px 16px;
  min-height: 60vh;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

/* ── Card ─────────────────────────────────────────── */
.dpp-card {
  width: 100%;
  max-width: 480px;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.08), 0 1px 4px rgba(0, 0, 0, 0.04);
  overflow: hidden;
  border: 1px solid #e8ecf0;
}

.dpp-card-warning {
  border-color: #d4380d;
  box-shadow: 0 4px 24px rgba(212, 56, 13, 0.12), 0 1px 4px rgba(212, 56, 13, 0.06);
}

/* ── Header ───────────────────────────────────────── */
.dpp-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #ffffff;
}

.dpp-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.dpp-logo .fa-shield {
  font-size: 22px;
  color: #4fd1c5;
}

.dpp-header-label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  opacity: 0.7;
  font-weight: 500;
}

/* ── Warning banner ───────────────────────────────── */
.dpp-warning-banner {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 14px 24px;
  background: #fff2e8;
  color: #873800;
  font-size: 13px;
  line-height: 1.5;
  border-bottom: 1px solid #ffd8bf;
}

.dpp-warning-banner .fa-exclamation-triangle {
  margin-top: 2px;
  color: #d4380d;
  flex-shrink: 0;
}

.dpp-card-warning .dpp-warning-banner {
  background: #fff1f0;
  color: #820014;
  border-bottom-color: #ffa39e;
}

/* ── Body ─────────────────────────────────────────── */
.dpp-body {
  padding: 28px 24px;
}

.dpp-product-section {
  margin-bottom: 4px;
}

.dpp-product-name {
  font-size: 22px;
  font-weight: 700;
  color: #1a1a2e;
  margin: 0 0 4px 0;
  line-height: 1.3;
}

.dpp-product-model {
  font-size: 15px;
  color: #595959;
  margin: 0 0 8px 0;
}

.dpp-product-manufacturer {
  font-size: 13px;
  color: #8c8c8c;
  margin: 0;
}

.dpp-product-manufacturer .fa {
  margin-right: 4px;
}

/* ── Divider ──────────────────────────────────────── */
.dpp-divider {
  border: none;
  border-top: 1px solid #f0f0f0;
  margin: 20px 0;
}

/* ── Info grid ────────────────────────────────────── */
.dpp-info-grid {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.dpp-info-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.dpp-info-label {
  font-size: 13px;
  font-weight: 600;
  color: #8c8c8c;
  text-transform: uppercase;
  letter-spacing: 0.6px;
}

/* ── Badges ───────────────────────────────────────── */
.dpp-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
}

.dpp-badge-good {
  background: #f6ffed;
  color: #135200;
  border: 1px solid #b7eb8f;
}

.dpp-badge-neutral {
  background: #fff7e6;
  color: #874d00;
  border: 1px solid #ffd591;
}

.dpp-badge-danger {
  background: #fff1f0;
  color: #820014;
  border: 1px solid #ffa39e;
}

/* ── Passport ID ──────────────────────────────────── */
.dpp-passport-id {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #f0f0f0;
}

.dpp-id-value {
  font-size: 14px;
  font-weight: 600;
  color: #1a1a2e;
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
  letter-spacing: 0.5px;
}

/* ── Footer ───────────────────────────────────────── */
.dpp-footer {
  padding: 16px 24px;
  background: #fafafa;
  border-top: 1px solid #f0f0f0;
  text-align: center;
}

.dpp-footer-line {
  font-size: 12px;
  color: #8c8c8c;
  line-height: 1.8;
}

.dpp-footer-line .fa {
  margin-right: 4px;
}

.dpp-footer-brand {
  font-size: 11px;
  color: #bfbfbf;
}

/* ── Empty state ──────────────────────────────────── */
.dpp-card-empty .dpp-body {
  padding: 40px 24px;
}

.dpp-empty-icon {
  font-size: 48px;
  color: #d9d9d9;
  margin-bottom: 16px;
}

.dpp-card-empty h3 {
  color: #595959;
  margin: 0 0 8px 0;
}

/* ── Responsive ───────────────────────────────────── */
@media (max-width: 480px) {
  .dpp-verify-wrapper {
    padding: 16px 8px;
  }
  .dpp-header {
    padding: 16px 20px;
  }
  .dpp-body {
    padding: 20px;
  }
  .dpp-product-name {
    font-size: 19px;
  }
  .dpp-info-item {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }
}

sp_widget.script:
(function () {
    data.found = false;
    data.product = '';
    data.model = '';
    data.manufacturer = '';
    data.passportStatus = '';
    data.passportStatusLabel = '';
    data.hasFraud = false;
    data.isWarning = false;
    data.warningMessage = '';
    data.assetId = '';
    data.scanDate = new GlideDateTime().getDisplayValue();

    var sysId = $sp.getParameter('sys_id');
    if (!sysId) { return; }

    var gr = new GlideRecord('x_1919710_refurt_0_asset_passport');
    if (!gr.get(sysId)) { return; }

    data.found = true;
    data.product = gr.getValue('name') || '';
    data.model = gr.getValue('model_number') || '';
    data.assetId = gr.getValue('asset_ta0') || '';

    // Dot-walk manufacturer reference safely
    if (!gr.manufacturer.nil()) {
        data.manufacturer = gr.manufacturer.getDisplayValue();
    }

    // Map passport_status to display label and severity
    var status = gr.getValue('passport_status') || 'unknown';
    data.passportStatus = status;

    var STATUS_MAP = {
        'active':             { label: 'Active',             severity: 'good' },
        'inspection_passed':  { label: 'Inspection Passed',  severity: 'good' },
        'pending_inspection': { label: 'Pending Inspection', severity: 'neutral' },
        'suspended':          { label: 'Suspended',          severity: 'danger' },
        'flagged':            { label: 'Flagged',            severity: 'danger' },
        'decommissioned':     { label: 'Decommissioned',    severity: 'neutral' }
    };

    var mapped = STATUS_MAP[status] || { label: status, severity: 'neutral' };
    data.passportStatusLabel = mapped.label;
    data.statusSeverity = mapped.severity;

    // Warning banner for flagged/suspended
    if (status === 'flagged' || status === 'suspended') {
        data.isWarning = true;
        data.warningMessage = status === 'flagged'
            ? 'This device has been flagged due to a reported issue. Exercise caution before purchasing.'
            : 'This device passport has been suspended. Verification cannot be completed at this time.';
    }

    // Check for confirmed fraud reports — only yes/no, no details exposed
    var fr = new GlideRecord('x_1919710_refurt_0_fraud_report');
    fr.addQuery('asset_passport', sysId);
    fr.addQuery('status', 'confirmed');
    fr.setLimit(1);
    fr.query();
    data.hasFraud = fr.hasNext();
})();
